CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS units(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,name TEXT NOT NULL,active INTEGER DEFAULT 1,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('ADMIN','SSMA','GESTOR','CONSULTA')),company_id TEXT,unit_id TEXT,active INTEGER DEFAULT 1,password_hash TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS occurrences(id TEXT PRIMARY KEY,company_id TEXT,unit_id TEXT,date TEXT,time TEXT,operation TEXT,location TEXT,city TEXT,uf TEXT,nature TEXT,type TEXT,potential TEXT,victim INTEGER DEFAULT 0,material_damage INTEGER DEFAULT 0,environmental_impact INTEGER DEFAULT 0,description TEXT,driver TEXT,document TEXT,plate TEXT,fleet TEXT,trailer TEXT,trailer_plate TEXT,bird_suggested TEXT,bird_reason TEXT,bird_validated TEXT,status TEXT DEFAULT 'Registrado',created_by TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS third_parties(id TEXT PRIMARY KEY,occurrence_id TEXT NOT NULL,type TEXT,name TEXT NOT NULL,contact_name TEXT,phone1 TEXT,phone2 TEXT,email TEXT,notes TEXT,FOREIGN KEY(occurrence_id) REFERENCES occurrences(id));
CREATE TABLE IF NOT EXISTS investigations(id TEXT PRIMARY KEY,occurrence_id TEXT UNIQUE NOT NULL,validated_bird TEXT,reclass_reason TEXT,immediate_cause TEXT,contributing_factors TEXT,root_cause TEXT,method TEXT,why1 TEXT,why2 TEXT,why3 TEXT,why4 TEXT,why5 TEXT,conclusion TEXT,updated_by TEXT,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(occurrence_id) REFERENCES occurrences(id));
CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY,occurrence_id TEXT NOT NULL,description TEXT NOT NULL,type TEXT,origin TEXT,responsible TEXT,deadline TEXT,priority TEXT,status TEXT,evidence TEXT,validation TEXT,effectiveness TEXT,effectiveness_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,FOREIGN KEY(occurrence_id) REFERENCES occurrences(id));
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,occurrence_id TEXT NOT NULL,action_id TEXT,object_key TEXT NOT NULL,file_name TEXT,mime_type TEXT,size INTEGER,uploaded_by TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS closures(id TEXT PRIMARY KEY,occurrence_id TEXT UNIQUE NOT NULL,conclusion TEXT,lessons TEXT,recommendations TEXT,responsible TEXT,closed_at TEXT NOT NULL,FOREIGN KEY(occurrence_id) REFERENCES occurrences(id));
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,occurrence_id TEXT,user_id TEXT,event TEXT NOT NULL,details TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_occ_company ON occurrences(company_id); CREATE INDEX IF NOT EXISTS idx_occ_unit ON occurrences(unit_id); CREATE INDEX IF NOT EXISTS idx_occ_date ON occurrences(date); CREATE INDEX IF NOT EXISTS idx_actions_occ ON actions(occurrence_id); CREATE INDEX IF NOT EXISTS idx_actions_deadline ON actions(deadline);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,user_id TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_sessions_token ON sessions(token_hash); CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);